/**
 * THE RUSTY ANCHOR — Scene Controller
 * Generated by Creation Kit v1.49
 *
 * Socket.IO connection, stat bar updaters, chat log, button wiring,
 * toast notifications, and scene lifecycle.
 *
 * Version: v1.49.0 [2026-03-21]
 * CONNECTS: Socket.IO, DOM elements
 * CALLED BY: DOMContentLoaded
 */
'use strict';

class TavernScene {
  constructor() {
    this.socket = null;
    this.state = null;
  }

  // ── Lifecycle ───────────────────────────────────────────────────

  init() {
    this._setupSocket();
    this._setupUI();
    this._loadInitialState();
  }

  _setupSocket() {
    this.socket = io();
    this.socket.on('connect', () => this._log('Connected to THE RUSTY ANCHOR', 'system'));
    this.socket.on('disconnect', () => this._log('Disconnected', 'system'));
    this.socket.on('state_update', (data) => this._applyState(data));
    this.socket.on('error', (data) => this._showToast(data.message || 'Error', 'danger'));
  }

  _loadInitialState() {
    fetch('/api/status')
      .then(r => r.ok ? r.json() : null)
      .then(data => { if (data) this._applyState(data); })
      .catch(() => {});
  }

  // ── State application ───────────────────────────────────────────

  _applyState(state) {
    if (!state) return;
    this.state = state;

    // Stat bar: stat-warmth
    if (state['stat-warmth'] !== undefined) {
      const el = document.getElementById('stat-warmth');
      const valEl = document.getElementById('val-stat-warmth');
      const max = state['stat-warmth_max'] || 100;
      const pct = Math.round((state['stat-warmth'] / max) * 100);
      if (el) el.style.width = pct + '%';
      if (valEl) valEl.textContent = state['stat-warmth'];
    }

    // Stat bar: stat-courage
    if (state['stat-courage'] !== undefined) {
      const el = document.getElementById('stat-courage');
      const valEl = document.getElementById('val-stat-courage');
      const max = state['stat-courage_max'] || 100;
      const pct = Math.round((state['stat-courage'] / max) * 100);
      if (el) el.style.width = pct + '%';
      if (valEl) valEl.textContent = state['stat-courage'];
    }

    // Stat bar: stat-clarity
    if (state['stat-clarity'] !== undefined) {
      const el = document.getElementById('stat-clarity');
      const valEl = document.getElementById('val-stat-clarity');
      const max = state['stat-clarity_max'] || 100;
      const pct = Math.round((state['stat-clarity'] / max) * 100);
      if (el) el.style.width = pct + '%';
      if (valEl) valEl.textContent = state['stat-clarity'];
    }

    // Stat bar: stat-charm
    if (state['stat-charm'] !== undefined) {
      const el = document.getElementById('stat-charm');
      const valEl = document.getElementById('val-stat-charm');
      const max = state['stat-charm_max'] || 100;
      const pct = Math.round((state['stat-charm'] / max) * 100);
      if (el) el.style.width = pct + '%';
      if (valEl) valEl.textContent = state['stat-charm'];
    }
  }

  // ── UI wiring ──────────────────────────────────────────────────

  _setupUI() {
    document.getElementById('btn-roll')?.addEventListener('click', () => this._action('roll'));
    document.getElementById('btn-investigate')?.addEventListener('click', () => this._action('investigate'));
    document.getElementById('drink-ale')?.addEventListener('click', () => this._action('order_drink', {drink: 'ale'}));
    document.getElementById('drink-wine')?.addEventListener('click', () => this._action('order_drink', {drink: 'wine'}));
    document.getElementById('drink-mead')?.addEventListener('click', () => this._action('order_drink', {drink: 'mead'}));
    document.getElementById('drink-spirits')?.addEventListener('click', () => this._action('order_drink', {drink: 'spirits'}));
    document.getElementById('drink-tea')?.addEventListener('click', () => this._action('order_drink', {drink: 'tea'}));
    document.getElementById('drink-mystery')?.addEventListener('click', () => this._action('order_drink', {drink: 'mystery'}));

    // Chat input: chat-input
    const chatInput = document.getElementById('chat-input');
    if (chatInput) {
      chatInput.addEventListener('keydown', (e) => {
        if (e.key === 'Enter' && chatInput.value.trim()) {
          this._sendMessage(chatInput.value.trim());
          chatInput.value = '';
        }
      });
    }
    // Send button (sibling of input)
    chatInput?.parentElement?.querySelector('button')?.addEventListener('click', () => {
      if (chatInput.value.trim()) {
        this._sendMessage(chatInput.value.trim());
        chatInput.value = '';
      }
    });
  }

  // ── Actions ──────────────────────────────────────────────────

  _action(action, data = {}) {
    if (this.socket) {
      this.socket.emit('action', { action, ...data });
      this._log(`Action: ${action}`, 'system');
    }
  }

  _sendMessage(text) {
    this._addChatLine(text, 'user');
    if (this.socket) {
      this.socket.emit('action', { action: 'message', text });
    }
  }

  // ── Chat log ──────────────────────────────────────────────────

  _addChatLine(text, type = '') {
    const feed = document.getElementById('chat-feed');
    if (!feed) return;
    const div = document.createElement('div');
    div.className = 'chat-entry ' + type;
    div.textContent = text;
    feed.appendChild(div);
    feed.scrollTop = feed.scrollHeight;
    while (feed.children.length > 80) feed.removeChild(feed.firstChild);
  }

  _log(text, type) { this._addChatLine(text, type); }

  _showToast(text) { console.debug('[toast]', text); }

}

// ── Bootstrap ───────────────────────────────────────────────────────
const SceneApp = new TavernScene();
document.addEventListener('DOMContentLoaded', () => SceneApp.init());
